package com.fitpulse.model.entity;
import jakarta.persistence.*;
@Entity @Table(name="gym_photos") public class GymPhoto { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(optional=false) private Gym gym; @Column(nullable=false,length=1000) private String imageUrl; @Column(nullable=false,length=250) private String altText; private int sortOrder; private boolean coverPhoto; public Long getId(){return id;} public Gym getGym(){return gym;} public void setGym(Gym v){gym=v;} public String getImageUrl(){return imageUrl;} public void setImageUrl(String v){imageUrl=v;} public String getAltText(){return altText;} public void setAltText(String v){altText=v;} public int getSortOrder(){return sortOrder;} public void setSortOrder(int v){sortOrder=v;} public boolean isCoverPhoto(){return coverPhoto;} public void setCoverPhoto(boolean v){coverPhoto=v;} }
